+import { Pool } from 'pg';
+
+interface SchemaColumn {
+  name: string;
+  type: string;
+  nullable: boolean;
+}
+
+interface TableSchema {
+  [tableName: string]: SchemaColumn[];
+}
+
+async function introspectSchema(): Promise<TableSchema> {
+  const pool = new Pool({ connectionString: process.env.DATABASE_URL });
+  try {
+    const result = await pool.query(`
+      SELECT
+        table_name,
+        column_name,
+        data_type,
+        is_nullable
+      FROM information_schema.columns
+      WHERE table_schema = 'public'
+      ORDER BY table_name, ordinal_position
+    `);
+
+    const schema: TableSchema = {};
+    for (const row of result.rows) {
+      if (!schema[row.table_name]) {
+        schema[row.table_name] = [];
+      }
+      schema[row.table_name].push({
+        name: row.column_name,
+        type: row.data_type,
+        nullable: row.is_nullable === 'YES',
+      });
+    }
+
+    return schema;
+  } finally {
+    await pool.end();
+  }
+}
+
+function validateSchema(actual: TableSchema, expected: TableSchema): string[] {
+  const errors: string[] = [];
+
+  // Check expected tables exist
+  for (const tableName of Object.keys(expected)) {
+    if (!actual[tableName]) {
+      errors.push(`Table "${tableName}" not found in database`);
+      continue;
+    }
+
+    const expectedCols = expected[tableName];
+    const actualCols = actual[tableName];
+    const actualColMap = new Map(actualCols.map(c => [c.name, c]));
+
+    for (const col of expectedCols) {
+      const actualCol = actualColMap.get(col.name);
+      if (!actualCol) {
+        errors.push(`Column "${tableName}.${col.name}" not found in database`);
+        continue;
+      }
+
+      // Basic type checking (simplistic - adjust for your types)
+      const expectedType = col.type.toLowerCase();
+      const actualType = actualCol.type.toLowerCase();
+      if (expectedType !== actualType) {
+        errors.push(
+          `Type mismatch for "${tableName}.${col.name}": ` +
+          `expected ${expectedType}, got ${actualType}`
+        );
+      }
+    }
+  }
+
+  return errors;
+}
+
+async function main() {
+  try {
+    if (!process.env.DATABASE_URL) {
+      console.warn('DATABASE_URL not set - skipping schema validation');
+      process.exit(0);
+    }
+
+    const actual = await introspectSchema();
+
+    // Define expected schema (mirrors src/db/schema.ts)
+    const expected: TableSchema = {
+      users: [
+        { name: 'id', type: 'text', nullable: false },
+        { name: 'email', type: 'text', nullable: false },
+        { name: 'created_at', type: 'timestamp without time zone', nullable: false },
+      ],
+      audit_log: [
+        { name: 'actor', type: 'text', nullable: false },
+        { name: 'action', type: 'text', nullable: false },
+      ],
+    };
+
+    const errors = validateSchema(actual, expected);
+
+    if (errors.length > 0) {
+      console.error('Schema validation failed:');
+      errors.forEach(err => console.error(`  ✗ ${err}`));
+      console.error('\nUpdate src/db/schema.ts to match the database schema');
+      process.exit(1);
+    }
+
+    console.log('✓ Schema validation passed - src/db/schema.ts matches database');
+  } catch (err) {
+    console.error('Schema validation error:', err);
+    process.exit(1);
+  }
+}
+
+main();
